54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        LocalDate registrationDate = BusinessDay.adjust(
108	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
109	        owner.setRegistrationDate(registrationDate);
110	        Collection<Owner> owners = this.clinicService.findAllOwners();
111	        if (owners.stream().filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() >= 100) {
112	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
113	        }
114	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
115	        if (owners.stream().anyMatch(existing -> existing.getTelephone().equals(owner.getTelephone()))
116	                || (!sharesHousehold && owners.stream().anyMatch(existing -> sameHousehold(existing, owner)))
117	                || owners.stream().filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 50) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        owner.setNamesakeCount((int) owners.stream()
121	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(owner.getFirstName())
122	                && existing.getLastName().equalsIgnoreCase(owner.getLastName()))
123	            .count());
124	        owner.setCustomerCode(CustomerCode.of(owner, owners));
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    /** Two owners share a household when their last name and address match, compared
133	     *  case-insensitively with runs of whitespace collapsed to a single space. */
134	    private static boolean sameHousehold(Owner a, Owner b) {
135	        return a.getLastName().equalsIgnoreCase(b.getLastName())
136	            && a.getAddress().trim().replaceAll("\\s+", " ")
137	                .equalsIgnoreCase(b.getAddress().trim().replaceAll("\\s+", " "));
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        currentOwner.setAddress(ownerFieldsDto.getAddress());
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Transactional
158	    @Override
159	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        this.clinicService.deleteOwner(owner);
165	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        HttpHeaders headers = new HttpHeaders();
176	        Pet pet = petMapper.toPet(petFieldsDto);
177	        owner.setId(ownerId);
178	        pet.setOwner(owner);
179	        pet.getType().setName(null);
180	        this.clinicService.savePet(pet);
181	        PetDto petDto = petMapper.toPetDto(pet);
182	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
183	            .buildAndExpand(pet.getId()).toUri());
184	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner != null) {
192	            Pet currentPet = this.clinicService.findPetById(petId);
193	            if (currentPet != null) {
194	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
195	                currentPet.setName(petFieldsDto.getName());
196	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
197	                this.clinicService.savePet(currentPet);
198	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	            }
200	        }
201	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
207	        HttpHeaders headers = new HttpHeaders();
208	        Visit visit = visitMapper.toVisit(visitFieldsDto);
209	        Pet pet = new Pet();
210	        pet.setId(petId);
211	        visit.setPet(pet);
212	        this.clinicService.saveVisit(visit);
213	        VisitDto visitDto = visitMapper.toVisitDto(visit);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
215	            .buildAndExpand(visit.getId()).toUri());
216	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
217	    }
218	
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner != null) {
225	            Pet pet = owner.getPet(petId);
226	            if (pet != null) {
227	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	}
