20	/**
21	 * Builds an owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>}:
22	 * the customer code followed by the last two digits of the registration date's year,
23	 * e.g. {@code SMI-0007-M26}.
24	 */
25	public final class MembershipNumber {
